import numpy as np
def equation(t, x, v, params):
    return params[0]*np.cos(params[1]*t) + params[2]*v + params[3]*x*v*v + params[4]*x**3

from scipy.optimize import least_squares
def model(p):
    A,w,ph,B,C,D,E,F,G=p
    return A*np.cos(w*t+ph)+B*v+C*x+D*v*np.abs(v)+E*x**3+F*x*v+G
best=None
for w0 in np.linspace(0.2,1.2,11):
    for ph0 in [0,1.5,3]:
        r=least_squares(lambda p: model(p)-dv_dt,[5,w0,ph0,-1,0,0,0,0,0])
        if best is None or r.cost<best.cost: best=r
print(best.x.round(4), best.cost, np.mean(best.fun**2)/np.var(dv_dt))

